<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetSnippetVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetCodeVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetTypeVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetContentVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetEnabledVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetVersionVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\Enable\SnippetAssetEnableResult;
use PHPUnit\Framework\TestCase;

final class SnippetAssetEnableResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new SnippetAssetEnableResult();
        $snippetOneValue = new SnippetRef('one');
        $snippetOtherValue = new SnippetRef('other');
        $copy = $value->snippet($snippetOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new SnippetRef('one'), $value->getSnippet());
        $this->assertNotEquals(new SnippetRef('other'), $value->getSnippet());
        $this->assertEquals(new SnippetRef('one'), $value->getSnippetOrCurrent(SnippetAssetSnippetVO::from($snippetOtherValue))->value());
        $this->assertNotEquals(new SnippetRef('other'), $value->getSnippetOrCurrent(SnippetAssetSnippetVO::from($snippetOtherValue))->value());
        $value->unsetSnippet();
        $this->assertEquals(new SnippetRef('other'), $value->getSnippetOrCurrent(SnippetAssetSnippetVO::from($snippetOtherValue))->value());
        $this->assertNotEquals(new SnippetRef('one'), $value->getSnippetOrCurrent(SnippetAssetSnippetVO::from($snippetOtherValue))->value());
        $codeOneValue = 'one';
        $codeOtherValue = 'other';
        $copy = $value->code($codeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCode());
        $this->assertNotEquals('other', $value->getCode());
        $this->assertEquals('one', $value->getCodeOrCurrent(SnippetAssetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('other', $value->getCodeOrCurrent(SnippetAssetCodeVO::from($codeOtherValue))->value());
        $value->unsetCode();
        $this->assertEquals('other', $value->getCodeOrCurrent(SnippetAssetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('one', $value->getCodeOrCurrent(SnippetAssetCodeVO::from($codeOtherValue))->value());
        $typeOneValue = 'one';
        $typeOtherValue = 'other';
        $copy = $value->type($typeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getType());
        $this->assertNotEquals('other', $value->getType());
        $this->assertEquals('one', $value->getTypeOrCurrent(SnippetAssetTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('other', $value->getTypeOrCurrent(SnippetAssetTypeVO::from($typeOtherValue))->value());
        $value->unsetType();
        $this->assertEquals('other', $value->getTypeOrCurrent(SnippetAssetTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('one', $value->getTypeOrCurrent(SnippetAssetTypeVO::from($typeOtherValue))->value());
        $contentOneValue = 'store://bin';
        $contentOtherValue = 'store://obin';
        $copy = $value->content($contentOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('store://bin', $value->getContent());
        $this->assertNotEquals('store://obin', $value->getContent());
        $this->assertEquals('bin', $value->getContentOrCurrent(SnippetAssetContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('obin', $value->getContentOrCurrent(SnippetAssetContentVO::from($contentOtherValue))->value());
        $value->unsetContent();
        $this->assertEquals('obin', $value->getContentOrCurrent(SnippetAssetContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('bin', $value->getContentOrCurrent(SnippetAssetContentVO::from($contentOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrCurrent(SnippetAssetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrCurrent(SnippetAssetEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrCurrent(SnippetAssetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrCurrent(SnippetAssetEnabledVO::from($enabledOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(SnippetAssetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(SnippetAssetVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(SnippetAssetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(SnippetAssetVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
